// #region 🔖ParseSections
export function parseSectionsFromLines(
  lines: string[],
  ext: string
): ParsedSection[] {
  const sections: ParsedSection[] = [];
  interface SectionFrame {
    name: string;
    startLine: number;
    level: number;
    path: string;
  }
  const stack: SectionFrame[] = [];

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1;
    const line = lines[i];
    const marker = parseRegionMarker(line);
    if (marker) {
      if (marker.isEnd) {
        if (stack.length > 0) {
          const frame = stack.pop()!;
          sections.push({
            name: frame.name,
            path: frame.path,
            startLine: frame.startLine,
            endLine: lineNumber - 1,
          });
        }
      } else {
        const path =
          stack.length > 0
            ? `${stack[stack.length - 1].path}.${marker.name}`
            : marker.name;
        stack.push({ name: marker.name, startLine: lineNumber, level: 0, path });
      }
      continue;
    }
    if (ext === ".md" || ext === ".mdx") {
      const heading = parseMarkdownHeading(line);
      if (heading) {
        while (
          stack.length > 0 &&
          stack[stack.length - 1].level >= heading.level
        ) {
          const frame = stack.pop()!;
          sections.push({
            name: frame.name,
            path: frame.path,
            startLine: frame.startLine,
            endLine: lineNumber - 1,
          });
        }
        const path =
          stack.length > 0
            ? `${stack[stack.length - 1].path}.${heading.title}`
            : heading.title;
        stack.push({
          name: heading.title,
          startLine: lineNumber,
          level: heading.level,
          path,
        });
      }
    }
  }

  for (const frame of stack) {
    sections.push({
      name: frame.name,
      path: frame.path,
      startLine: frame.startLine,
      endLine: lines.length,
    });
  }
