    const lineNumber = i + 1;
    for (const pattern of patterns) {
      const match = lines[i].match(pattern);
      if (match && match.length > 1) {
        defs.push({
          name: match[match.length - 1],
          startLine: lineNumber,
          endLine: lineNumber,
        });
