import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { listEvents } from "@/lib/db";
import { requireAuth, isAuthError } from "@/lib/auth";
import { publishEvent } from "@/lib/events";

const EventSchema = z.object({
